//! The renderers: golden output for the canonical example, the determinism
//! guarantee (same plan in, byte-identical file out — including across
//! authoring order), and the self-containment of the HTML. The HTML graph's
//! layout goldens are hand-computed from the constants in `src/render.rs`
//! and pinned byte-exactly, per direction. The gantt's goldens come from
//! the schedule artifact (the golden dates are the scheduler test's,
//! generated by the binary, never hand-computed); its CLI cases run the
//! real binary over tempdirs.

use std::process::Command;

use planning_dsl::render::Direction;
use planning_dsl::{Plan, load, render, schedule};

macro_rules! fixture {
    ($name:literal) => {
        include_str!(concat!("fixtures/", $name))
    };
}

const PLAN: &str = fixture!("plan.yaml");

#[test]
fn the_canonical_example_renders_the_expected_mermaid() {
    let plan = load(PLAN).expect("parses");
    assert_eq!(
        render::mermaid(&plan),
        "flowchart TD\n\
         \x20   design-architecture[\"design-architecture\"]\n\
         \x20   plan-out-the-tasks[\"plan-out-the-tasks\"]\n\
         \x20   implement-services[\"implement-services\"]\n\
         \x20   implement-tests[\"implement-tests\"]\n\
         \x20   design-architecture --> plan-out-the-tasks\n\
         \x20   plan-out-the-tasks --> implement-services\n\
         \x20   plan-out-the-tasks --> implement-tests\n"
    );
}

#[test]
fn mermaid_edges_point_from_a_dependency_to_its_dependent() {
    // The community convention: arrows follow execution order.
    let plan = load(PLAN).expect("parses");
    let mmd = render::mermaid(&plan);
    assert!(
        mmd.contains("    design-architecture --> plan-out-the-tasks\n"),
        "{mmd}"
    );
    assert!(
        !mmd.contains("plan-out-the-tasks --> design-architecture"),
        "{mmd}"
    );
}

#[test]
fn authoring_order_is_meaningful_so_renders_follow_declaration_order() {
    // Declaration order is load-bearing (the scheduler's tie-break), so two
    // files that declare the same tasks in different orders are different
    // plans: their renders may order nodes differently but must carry the
    // same nodes and edges, and each is byte-identical across runs.
    let a = "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
tasks:
  ship: { role: dev, depends-on: [build, test] }
  test: { role: dev, estimate: 2 }
  build: { role: dev, estimate: 3 }
executors:
  anton: { roles: [dev] }
";
    let b = "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
tasks:
  build: { role: dev, estimate: 3 }
  ship: { role: dev, depends-on: [test, build] }
  test: { role: dev, estimate: 2 }
executors:
  anton: { roles: [dev] }
";
    let a = load(a).expect("parses");
    let b = load(b).expect("parses");
    // Mermaid: same lines up to order. HTML: geometry differs with the row
    // order, so compare the carried data instead — the node ids and the
    // edge pairs.
    let sorted = |s: &str| -> Vec<String> {
        let mut lines: Vec<String> = s.lines().map(str::to_string).collect();
        lines.sort();
        lines
    };
    assert_eq!(sorted(&render::mermaid(&a)), sorted(&render::mermaid(&b)));
    let html_data = |html: &str| -> (Vec<String>, Vec<String>) {
        let mut ids: Vec<String> = html
            .lines()
            .filter(|l| l.contains("data-id="))
            .filter_map(|l| l.split("data-id=\"").nth(1))
            .filter_map(|rest| rest.split('"').next())
            .map(str::to_string)
            .collect();
        ids.sort();
        let mut edges: Vec<String> = html
            .lines()
            .filter(|l| l.contains("class=\"edge\""))
            .filter_map(|l| {
                let from = l.split("data-from=\"").nth(1)?.split('"').next()?;
                let to = l.split("data-to=\"").nth(1)?.split('"').next()?;
                Some(format!("{from}->{to}"))
            })
            .collect();
        edges.sort();
        (ids, edges)
    };
    assert_eq!(
        html_data(&render::html(&a, Direction::Tb)),
        html_data(&render::html(&b, Direction::Tb))
    );
    // Determinism per plan, run over run.
    assert_eq!(render::mermaid(&a), render::mermaid(&a));
    assert_eq!(
        render::html(&b, Direction::Tb),
        render::html(&b, Direction::Tb)
    );
    // The node order follows the declaration order of each file.
    let a_mermaid = render::mermaid(&a);
    let a_nodes: Vec<&str> = a_mermaid
        .lines()
        .filter(|l| l.contains("[\""))
        .map(|l| l.split('"').nth(1).expect("quoted"))
        .collect();
    assert_eq!(a_nodes, ["ship", "test", "build"]);
}

#[test]
fn a_task_name_mermaid_cannot_use_pushes_every_node_to_synthetic_ids() {
    // `end` breaks mermaid flowcharts; the whole diagram falls back to t0…tN.
    let yaml = "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
tasks:
  end: { role: dev }
  start: { role: dev, depends-on: [end] }
executors:
  anton: { roles: [dev] }
";
    let plan = load(yaml).expect("parses");
    let mmd = render::mermaid(&plan);
    assert!(mmd.contains("t0[\"end\"]"), "{mmd}");
    assert!(mmd.contains("    t0 --> t1\n"), "{mmd}");
    assert!(!mmd.contains("end["), "{mmd}");
}

#[test]
fn labels_are_escaped_in_both_renders() {
    // Names like these are refused at the door now (the slug rule), but the
    // renderers stay library functions over `Plan`: defensively, the escape
    // discipline holds for a plan that bypassed validation — the four
    // characters that break mermaid or XML, as entities, on the task name
    // and, in the HTML, on the `role · estimate` line too.
    let yaml = "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
  r&d: researches
tasks:
  fix&ship: { role: dev }
  a<b: { role: dev }
  research: { role: r&d, estimate: 3 }
executors:
  anton: { roles: [dev, r&d] }
";
    let plan = load(yaml).expect("parses");
    let mmd = render::mermaid(&plan);
    assert!(mmd.contains("t0[\"fix&amp;ship\"]"), "{mmd}");
    assert!(mmd.contains("a&lt;b"), "{mmd}");
    let html = render::html(&plan, Direction::Tb);
    assert!(html.contains("fix&amp;ship"), "{html}");
    assert!(!html.contains("fix&ship"), "{html}");
    assert!(!html.contains("a<b"), "{html}");
    assert!(
        html.contains("<text class=\"sub\" x=\"10\" y=\"28\">r&amp;d · 3</text>"),
        "{html}"
    );
    assert!(!html.contains("r&d"), "{html}");
}

#[test]
fn the_html_is_a_self_contained_file() {
    let plan = load(PLAN).expect("parses");
    let html = render::html(&plan, Direction::Tb);
    assert!(
        html.contains("<svg xmlns=\"http://www.w3.org/2000/svg\""),
        "{html}"
    );
    assert!(html.contains("<script>"), "{html}");
    assert!(!html.contains("<script src="), "{html}");
    assert!(!html.contains("<link "), "{html}");
    assert!(!html.contains("https://"), "{html}");
    assert_eq!(
        html.matches("http://").count(),
        1,
        "the only URL is the SVG xmlns"
    );
}

#[test]
fn every_task_is_one_node_and_every_dependency_one_edge() {
    let plan = load(PLAN).expect("parses");
    let html = render::html(&plan, Direction::Tb);
    // One of the four, design-architecture, is done and wears the muted
    // class; the count is over both shapes.
    assert_eq!(html.matches("class=\"node\"").count(), 3, "{html}");
    assert_eq!(html.matches("class=\"node done\"").count(), 1, "{html}");
    assert_eq!(html.matches("class=\"edge\"").count(), 3, "{html}");
    assert!(
        html.contains("data-from=\"plan-out-the-tasks\" data-to=\"implement-services\""),
        "{html}"
    );
    for name in [
        "design-architecture",
        "plan-out-the-tasks",
        "implement-services",
        "implement-tests",
    ] {
        assert!(html.contains(&format!("data-id=\"{name}\"")), "{html}");
    }
}

#[test]
fn a_dependency_naming_no_task_is_skipped_not_rendered() {
    let yaml = "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
tasks:
  ship: { role: dev, depends-on: [ghost, build] }
  build: { role: dev }
executors:
  anton: { roles: [dev] }
";
    let plan = load(yaml).expect("parses");
    let mmd = render::mermaid(&plan);
    assert!(!mmd.contains("ghost"), "{mmd}");
    let html = render::html(&plan, Direction::Tb);
    assert!(!html.contains("ghost"), "{html}");
    assert_eq!(html.matches("class=\"node\"").count(), 2, "{html}");
    assert_eq!(html.matches("class=\"edge\"").count(), 1, "{html}");
}

// The HTML graph's layout. Both directions are pinned byte-exactly against
// a three-task plan, hand-computed from `src/render.rs`'s constants: every
// label fits under MIN_W=100, so each node is 100 wide; two layers, two
// rows of which the widest is 100+60+100=260; MARGIN=24, ROW_H=56, H_GAP=60.

fn direction_plan() -> Plan {
    load(
        "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
tasks:
  ship: { role: dev, depends-on: [build, test] }
  test: { role: dev, estimate: 2 }
  build: { role: dev, estimate: 3 }
executors:
  anton: { roles: [dev] }
",
    )
    .expect("parses")
}

#[test]
fn the_lr_layout_keeps_the_flow_left_to_right() {
    // A column per layer: dependencies at x=24, the dependent at
    // 24 + (100+60) = 184. The canvas is 24 + 2*160 = 344 wide and
    // 24*2 + 2*56 = 160 tall; a one-node row centers vertically, its top at
    // 24 + (2-1)*56/2 = 52. Edges leave the right edge at mid-height
    // (y+20), enter the left edge, control points at the horizontal
    // midpoint (x=154).
    let html = render::html(&direction_plan(), Direction::Lr);
    assert!(
        html.contains(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"344\" height=\"160\" \
             data-w=\"344\" data-h=\"160\">"
        ),
        "{html}"
    );
    assert!(
        html.contains("data-id=\"test\" transform=\"translate(24,24)\""),
        "{html}"
    );
    assert!(
        html.contains("data-id=\"build\" transform=\"translate(24,80)\""),
        "{html}"
    );
    assert!(
        html.contains("data-id=\"ship\" transform=\"translate(184,52)\""),
        "{html}"
    );
    assert!(
        html.contains("d=\"M 124,44 C 154,44 154,72 184,72\""),
        "{html}"
    );
    assert!(
        html.contains("d=\"M 124,100 C 154,100 154,72 184,72\""),
        "{html}"
    );
}

#[test]
fn the_tb_layout_stacks_the_layers_top_down() {
    // A row per layer: the dependencies fill the top row from x=24 (the
    // widest row, 260, is the canvas' flow width), the dependent's row
    // centers at 24 + (260-100)/2 = 104. The canvas is 24*2+260 = 308 wide
    // and 24*2 + 2*56 = 160 tall. Edges leave the bottom-center
    // (x+50, y+40), enter the top-center, control points at the vertical
    // midpoint (y=72).
    let html = render::html(&direction_plan(), Direction::Tb);
    assert!(
        html.contains(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"308\" height=\"160\" \
             data-w=\"308\" data-h=\"160\">"
        ),
        "{html}"
    );
    assert!(
        html.contains("data-id=\"test\" transform=\"translate(24,24)\""),
        "{html}"
    );
    assert!(
        html.contains("data-id=\"build\" transform=\"translate(184,24)\""),
        "{html}"
    );
    assert!(
        html.contains("data-id=\"ship\" transform=\"translate(104,80)\""),
        "{html}"
    );
    assert!(
        html.contains("d=\"M 74,64 C 74,72 154,72 154,80\""),
        "{html}"
    );
    assert!(
        html.contains("d=\"M 234,64 C 234,72 154,72 154,80\""),
        "{html}"
    );
}

#[test]
fn nodes_carry_a_role_estimate_second_line() {
    // The second line is `role · estimate`, the estimate written bare
    // ("6", "4.5"); without an estimate, just the role. The width follows
    // the longer line: `io`'s name is 2 chars (36px) but its role line
    // `ux-writer · 4.5` is 15 chars (140px), and that wins; `api` and
    // `docs` both fall under MIN_W=100.
    let yaml = "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
  ux-writer: writes the words users see
tasks:
  io: { role: ux-writer, estimate: 4.5 }
  api: { role: dev, estimate: 6 }
  docs: { role: dev }
executors:
  anton: { roles: [dev, ux-writer] }
";
    let plan = load(yaml).expect("parses");
    let html = render::html(&plan, Direction::Tb);
    assert!(
        html.contains("<text class=\"sub\" x=\"10\" y=\"28\">ux-writer · 4.5</text>"),
        "{html}"
    );
    assert!(
        html.contains("<text class=\"sub\" x=\"10\" y=\"28\">dev · 6</text>"),
        "{html}"
    );
    assert!(
        html.contains("<text class=\"sub\" x=\"10\" y=\"28\">dev</text>"),
        "{html}"
    );
    assert!(
        html.contains("<rect width=\"140\" height=\"40\" rx=\"6\"/>"),
        "{html}"
    );
    assert_eq!(
        html.matches("<rect width=\"100\" height=\"40\" rx=\"6\"/>")
            .count(),
        2,
        "{html}"
    );
    // The canonical example's labels, on the fixture: a done task without
    // an estimate shows the bare role.
    let html = render::html(&load(PLAN).expect("parses"), Direction::Tb);
    assert!(
        html.contains("<text class=\"sub\" x=\"10\" y=\"28\">architect</text>"),
        "{html}"
    );
    assert!(
        html.contains("<text class=\"sub\" x=\"10\" y=\"28\">planner · 6</text>"),
        "{html}"
    );
    assert!(
        html.contains("<text class=\"sub\" x=\"10\" y=\"28\">tester · 16</text>"),
        "{html}"
    );
}

#[test]
fn the_corner_legend_states_the_unit_once_and_grey_only_when_done() {
    // The unit line is unconditional; the grey key appears only when a done
    // task gives it something to explain. One div per line, so a future key
    // joins as one more line.
    let html = render::html(&load(PLAN).expect("parses"), Direction::Tb);
    assert!(
        html.contains(
            "<div id=\"legend\">\n<div>unit: person-hours</div>\n\
             <div>grey: done</div>\n</div>"
        ),
        "{html}"
    );
    let yaml = "
unit: person-hours
deadline: 2026-12-18
roles:
  dev: implements
tasks:
  build: { role: dev, estimate: 3 }
executors:
  anton: { roles: [dev] }
";
    let html = render::html(&load(yaml).expect("parses"), Direction::Tb);
    assert!(
        html.contains("<div id=\"legend\">\n<div>unit: person-hours</div>\n</div>"),
        "{html}"
    );
    assert!(!html.contains("grey: done"), "{html}");
}

#[test]
fn done_tasks_are_muted_but_stay_in_the_graph() {
    // design-architecture is done: it keeps its node and its outgoing edge
    // but wears the done class — muted fill, stroke, text. Hover
    // highlighting keeps working on it: the hot rules are more specific
    // than the done rules, so no carve-out is needed.
    let html = render::html(&load(PLAN).expect("parses"), Direction::Tb);
    assert!(
        html.contains("class=\"node done\" data-id=\"design-architecture\""),
        "{html}"
    );
    assert!(
        html.contains("data-from=\"design-architecture\" data-to=\"plan-out-the-tasks\""),
        "{html}"
    );
    assert!(
        html.contains(".node.done rect { fill: #f1f2ee; stroke: #c4cad2; }"),
        "{html}"
    );
    assert!(
        html.contains(".node.done text { fill: #9aa4b2; }"),
        "{html}"
    );
}

#[test]
fn html_is_byte_identical_per_direction() {
    let plan = load(PLAN).expect("parses");
    assert_eq!(
        render::html(&plan, Direction::Tb),
        render::html(&plan, Direction::Tb)
    );
    assert_eq!(
        render::html(&plan, Direction::Lr),
        render::html(&plan, Direction::Lr)
    );
}

// The gantt: a function of the schedule artifact alone. Its golden dates are
// the scheduler test's goldens (`cargo run -- schedule tests/fixtures/plan.yaml`,
// walked by hand in tests/schedule.rs), never recomputed here.

fn scheduled_gantt(yaml: &str) -> String {
    let plan = load(yaml).expect("parses");
    let report = planning_dsl::validate(&plan);
    assert!(report.is_ok(), "fixture must validate: {:?}", report.errors);
    render::gantt(&schedule(&plan).expect("schedules"))
}

#[test]
fn the_canonical_example_renders_the_expected_gantt() {
    assert_eq!(
        scheduled_gantt(PLAN),
        "gantt\n\
         \x20   dateFormat YYYY-MM-DD\n\
         \x20   axisFormat %Y-%m-%d\n\
         \x20   section nikita\n\
         \x20   plan-out-the-tasks :crit, 2026-11-10, 2026-11-11\n\
         \x20   section anton\n\
         \x20   implement-services :crit, 2026-11-12, 2026-11-18\n\
         \x20   section review-agent\n\
         \x20   implement-tests :2026-11-12, 2026-11-13\n"
    );
}

#[test]
fn a_done_task_takes_no_bar_and_no_section() {
    // design-architecture is done: the artifact gives it no dates and no
    // executor, so it takes neither a bar nor an empty section — off the
    // gantt entirely, the choice pinned here. The three bars are the three
    // dated tasks.
    let gantt = scheduled_gantt(PLAN);
    assert!(!gantt.contains("design-architecture"), "{gantt}");
    assert_eq!(gantt.matches("    section ").count(), 3, "{gantt}");
    assert_eq!(gantt.matches(" :").count(), 3, "{gantt}");
}

#[test]
fn executor_sections_follow_first_appearance_not_executor_declaration() {
    // `a` is declared first but is out cold on day one (availability 0), so
    // `first` goes to `b` and `second` only reaches `a` the day after. The
    // artifact carries no executor order, so the gantt reads it off the task
    // declaration order: b's section first, a's second.
    let yaml = "
unit: person-hours
start: 2026-11-02
roles:
  dev: implements
tasks:
  first: { role: dev, estimate: 8 }
  second: { role: dev, estimate: 8 }
executors:
  a:
    roles: [dev]
    calendar: all
    availability:
      - { from: 2026-11-02, until: 2026-11-02, fraction: 0.0 }
  b: { roles: [dev], calendar: all }
";
    let gantt = scheduled_gantt(yaml);
    let b = gantt.find("    section b\n").expect("b sectioned");
    let a = gantt.find("    section a\n").expect("a sectioned");
    assert!(b < a, "{gantt}");
    assert!(gantt[b..].find("    first :").is_some(), "{gantt}");
    assert!(gantt[a..].find("    second :").is_some(), "{gantt}");
}

#[test]
fn critical_path_tasks_are_tagged_crit_and_others_are_not() {
    let gantt = scheduled_gantt(PLAN);
    assert!(
        gantt.contains("    implement-services :crit, 2026-11-12, 2026-11-18\n"),
        "{gantt}"
    );
    assert!(
        gantt.contains("    implement-tests :2026-11-12, 2026-11-13\n"),
        "{gantt}"
    );
}

#[test]
fn the_same_schedule_renders_the_gantt_byte_identically() {
    let plan = load(PLAN).expect("parses");
    let a = render::gantt(&schedule(&plan).expect("schedules"));
    let b = render::gantt(&schedule(&plan).expect("schedules"));
    assert_eq!(a, b);
}

// There is no gantt escape test: the slug rule refuses a non-slug name at
// the validator, and the scheduler gates on the validator — no public route
// carries a `fix&ship`-shaped name to a gantt bar. The class the old test
// exercised is the one identifying-names-are-kebab-case-slugs retired.

#[test]
fn a_plan_with_nothing_left_to_do_renders_the_empty_frame() {
    // The all-done artifact carries no dates at all (the autodecision): the
    // gantt still renders — the frame, no bars, no sections.
    let yaml = "
unit: person-hours
start: 2026-11-02
deadline: 2026-11-30
roles:
  dev: implements
tasks:
  seed: { status: done, role: dev }
executors:
  anton: { roles: [dev] }
";
    assert_eq!(
        scheduled_gantt(yaml),
        "gantt\n    dateFormat YYYY-MM-DD\n    axisFormat %Y-%m-%d\n"
    );
}

// The CLI: the gantt is opt-in, and a scheduler refusal leaves no half-drawn
// set behind — everything is computed before anything is written.

fn tempdir(name: &str) -> std::path::PathBuf {
    let dir =
        std::env::temp_dir().join(format!("planning-dsl-render-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("tempdir");
    dir
}

fn render_cli(dir: &std::path::Path, yaml: &str, args: &[&str]) -> std::process::Output {
    let plan = dir.join("plan.yaml");
    std::fs::write(&plan, yaml).expect("fixture copy");
    let mut argv = vec![
        "render".to_string(),
        plan.to_str().expect("utf-8 tempdir").to_string(),
    ];
    argv.extend(args.iter().map(|s| s.to_string()));
    Command::new(binary())
        .args(&argv)
        .output()
        .expect("the binary runs")
}

/// The binary under test. `CARGO_BIN_EXE_planning_dsl` is the sanctioned
/// handle, but this cargo does not always expose it to test compilation, so
/// fall back to the sibling of the test's own target dir — the same
/// `<target>/<profile>/planning-dsl` the env var would name.
fn binary() -> std::path::PathBuf {
    let fallback = || {
        let exe = std::env::current_exe().expect("the test binary knows where it is");
        exe.ancestors()
            .nth(2)
            .expect("the profile dir above deps/")
            .join("planning-dsl")
    };
    std::env::var_os("CARGO_BIN_EXE_planning_dsl")
        .map(Into::into)
        .unwrap_or_else(fallback)
}

#[test]
fn the_cli_writes_the_gantt_only_when_asked() {
    let dir = tempdir("opt-in");
    // Bare `render`: the two always-on renders, no gantt file.
    let out = render_cli(&dir, PLAN, &[]);
    assert!(out.status.success(), "{:?}", out);
    assert!(dir.join("plan.mmd").exists());
    assert!(dir.join("plan.html").exists());
    assert!(!dir.join("plan.gantt.mmd").exists());
    // `--gantt`, unnamed: the default name beside the others.
    let out = render_cli(&dir, PLAN, &["--gantt"]);
    assert!(out.status.success(), "{:?}", out);
    let gantt = std::fs::read_to_string(dir.join("plan.gantt.mmd")).expect("the gantt written");
    assert!(gantt.starts_with("gantt\n"), "{gantt}");
    assert!(gantt.contains("plan-out-the-tasks :crit,"), "{gantt}");
}

#[test]
fn the_cli_accepts_an_explicit_gantt_file() {
    let dir = tempdir("explicit");
    let named = dir.join("chart.mmd");
    let out = render_cli(&dir, PLAN, &["--gantt", named.to_str().expect("utf-8")]);
    assert!(out.status.success(), "{:?}", out);
    assert!(named.exists());
}

#[test]
fn the_html_graph_is_top_down_by_default() {
    // The default lives at the flag: the CLI writes tb without one, and its
    // bytes are exactly render::html's Direction::Tb — the fixture's tb
    // canvas is 412x216, its lr one 720x160.
    let plan = load(PLAN).expect("parses");
    let dir = tempdir("default-direction");
    let out = render_cli(&dir, PLAN, &[]);
    assert!(out.status.success(), "{:?}", out);
    let written = std::fs::read_to_string(dir.join("plan.html")).expect("the html written");
    assert_eq!(written, render::html(&plan, Direction::Tb));
    assert!(
        written.contains("width=\"412\" height=\"216\""),
        "{written}"
    );

    let dir = tempdir("lr-direction");
    let out = render_cli(&dir, PLAN, &["--direction", "lr"]);
    assert!(out.status.success(), "{:?}", out);
    let written = std::fs::read_to_string(dir.join("plan.html")).expect("the html written");
    assert_eq!(written, render::html(&plan, Direction::Lr));
    assert!(
        written.contains("width=\"720\" height=\"160\""),
        "{written}"
    );
}

#[test]
fn the_cli_rejects_an_unknown_direction() {
    let dir = tempdir("bad-direction");
    let out = render_cli(&dir, PLAN, &["--direction", "diagonal"]);
    assert!(!out.status.success(), "{:?}", out);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("tb or lr"), "{stderr}");
    // A missing value is the same refusal.
    let out = render_cli(&dir, PLAN, &["--direction"]);
    assert!(!out.status.success(), "{:?}", out);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("tb or lr"), "{stderr}");
}

#[test]
fn a_scheduler_refusal_writes_nothing_even_with_the_gantt_asked() {
    // No `start:` — the scheduler refuses, and the run must leave no files:
    // not the gantt, not the flowchart it would have managed without it.
    let dir = tempdir("refusal");
    let out = render_cli(
        &dir,
        include_str!("fixtures/plan-without-dates.yaml"),
        &["--gantt"],
    );
    assert!(!out.status.success(), "{:?}", out);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("no start"), "{stderr}");
    assert_eq!(
        std::fs::read_dir(&dir).expect("dir").count(),
        1, // the copied plan.yaml is the only file
        "no artifact files were written"
    );
}
